package uk.ac.ravensbourne.casevault.service;
import java.util.UUID; import org.springframework.stereotype.Service; import uk.ac.ravensbourne.casevault.domain.CaseRecord; import uk.ac.ravensbourne.casevault.domain.Role; import uk.ac.ravensbourne.casevault.repository.CaseRepository; import uk.ac.ravensbourne.casevault.security.*;
/** Loads cases and applies service-layer authorisation before returning any object (CWE-639). */
@Service public class CaseAccessService { private final CaseRepository cases; private final AccessPolicy policy; private final AccessDeniedAuditService audit; public CaseAccessService(CaseRepository cases,AccessPolicy policy,AccessDeniedAuditService audit){this.cases=cases;this.policy=policy;this.audit=audit;} @RequiresCaseAccess public CaseRecord requireView(UserPrincipal p,UUID id){var c=Role.CLIENT_USER.name().equals(p.role())?cases.findByIdAndOrganisationId(id,p.organisationId()).orElseGet(()->deny(p,id)):cases.findById(id).orElseGet(()->deny(p,id));boolean assigned=cases.existsAssignment(id,p.id());if(!p.enabled()||!policy.canViewCase(p,c,assigned))deny(p,id);return c;} @RequiresCaseAccess public CaseRecord requireReportApproval(UserPrincipal p,UUID id,UUID generatedBy){var c=requireView(p,id);if(!policy.canApproveReport(p,c,generatedBy))deny(p,id);return c;} private CaseRecord deny(UserPrincipal p,UUID id){audit.record(p,"case:"+id);throw new CaseNotFoundException();} }
